{
  "summary": "Gather current Acme Cloud contract terms, renewal/price-increase policy, SLA performance history, and any outstanding invoices/credits, then draft a reply addressing the renewal and 12% increase.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (term, pricing, renewal clauses, currency), any internal policy on vendor price increases/renewal negotiation limits, SLA performance records for the contract period, and outstanding invoices; use the SLA credit calculator to determine any credits owed to us for SLA misses, and use the currency converter if contract amounts are in USD or another foreign currency.",
      "why": "All facts about current pricing, contract terms, SLA performance, and any owed credits must be confirmed before responding to the renewal and price increase request."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the vendor email response to Acme Cloud Services addressing the 12-month renewal, evaluating the proposed 12% price increase against contract terms and policy, and including any SLA credits owed, for human review and approval.",
      "why": "The executor synthesizes the gathered facts into the final reply for the vendor, which a human will then review and approve."
    }
  ],
  "escalate": null
}
